let currentUser=null,currentProjects=[],currentProjectId=localStorage.getItem('projectId')||'',projectQuery='',projectStatus='全部项目',meetingFrom='',meetingTo='',meetingMine=false,logAuthorFilter='全部成员',logQuery='',logFrom='',logTo='',eventTypeFilter='全部动态',eventPersonFilter='全部成员',eventFrom='',eventTo='',showMine=false,workMemberFilter='全部成员',workQuery='',eventLimit=20,notificationPollTimer=null;
function uniquePersonByName(name){const matches=(state?.people||[]).filter(p=>p.name===name);return matches.length===1?matches[0]:null}
function belongsToCurrent(storedId,name,user=currentUser){return !!user&&(storedId?storedId===user.id:uniquePersonByName(name)?.id===user.id)}
function normalizeSearch(value){return String(value??'').normalize('NFKC').toLocaleLowerCase('zh-CN').replace(/[\u200b\ufeff]/g,'').replace(/[，。；：！？、,.!?;:()（）【】\[\]{}“”‘’\"'`~～·…—–_\-]+/g,' ').replace(/\s+/g,' ').trim()}
function fuzzyTermMatch(text,term){if(text.includes(term))return true;if(Array.from(term).length<3)return false;let i=0;for(const char of text){if(char===term[i]&&++i===Array.from(term).length)return true}return false}
function searchMatches(queryText,...values){const query=normalizeSearch(queryText);if(!query)return true;const corpus=normalizeSearch(values.flat(Infinity).filter(value=>value!==null&&value!==undefined).join(' '));return query.split(' ').filter(Boolean).every(term=>fuzzyTermMatch(corpus,term))}
