  const expandedKeys=projectTimelineExpanded.get(key),matchingMeetings=hasFilters?filtered.filter(n=>n.type==='meeting'&&n.matchCount):[],matchesExpanded=matchingMeetings.length>0&&matchingMeetings.every(n=>expandedKeys.has(n.key));
  const kinds=[...new Set(['会议','签到','纪要','资料','工作分配','工作日志','成员','项目','重点',...data.nodes.flatMap(n=>[n.kind,...(n.activities||[]).map(e=>e.kind)])])];
