function openFocusEditor(type,id){const team=markFor(type,id,'team'),mine=markFor(type,id,'personal'),initialScope=currentUser.role==='组长'&&focusScope==='team'&&state.project.status!=='已归档'?'team':'personal',initialMark=initialScope==='team'?team:mine||team,item=type==='meeting'?state.meetings.find(x=>x.id===id):type==='assignment'?state.assignments.find(x=>x.id===id):type==='log'?state.logs.find(x=>x.id===id):type==='file'?state.files.find(x=>x.id===id):state.meetings.find(x=>x.id===id),title=type==='meeting'?item?.title:type==='assignment'?item?.content:type==='log'?item?.text?.slice(0,80):type==='minutes'?`${item?.title||''} 会议纪要`:item?.name;modal('设置关注星级',`<div class="subtle">${esc(title||'项目记录')}</div><form id="focus-form"><input type="hidden" name="targetType" value="${esc(type)}"><input type="hidden" name="targetId" value="${esc(id)}"><div class="field"><label>关注口径</label><select name="scope"><option value="personal" ${initialScope==='personal'?'selected':''}>我的重点（仅本人可见）</option>${currentUser.role==='组长'?`<option value="team" ${state.project.status==='已归档'?'disabled':initialScope==='team'?'selected':''}>全队重点${state.project.status==='已归档'?'（已归档，只读）':'（成员可见）'}</option>`:''}</select></div><div class="field"><label>星级</label><select name="stars"><option value="0">无星级</option><option value="1" ${(initialMark?.stars||0)===1?'selected':''}>★ 一般关注</option><option value="2" ${(initialMark?.stars||0)===2?'selected':''}>★★ 重要参考</option><option value="3" ${(initialMark?.stars||0)===3?'selected':''}>★★★ 优先关注</option></select></div><div class="field"><label>重要性备注（最多500字）</label><textarea name="note" maxlength="500" rows="3">${esc(initialMark?.note||'')}</textarea></div>${mine?'<label class="restore-mark"><input type="checkbox" name="restoreTeam" value="yes"> 恢复使用全队设置</label>':''}</form>`,'保存关注设置');syncFocusEditorFields()}
