function render(){const navigationKey=JSON.stringify([currentUser?.id,currentProjectId,currentView,projectTimelineView,selectedMeeting?.id]);if(navigationKey!==projectTimelineNavigationKey){++projectEventSourceVersion;projectTimelineNavigationKey=navigationKey}if(currentView==='profile'){const el=$('#page-content');el.innerHTML=profilePage();syncUserMenu();const crumb=$('.breadcrumbs strong');if(crumb)crumb.textContent='个人账户';return}if(!state){if(currentView==='today'){$('#page-content').innerHTML=todayAgenda();document.querySelectorAll('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view==='today'));syncUserMenu();return}renderProjects();syncUserMenu();return}if(currentView==='projects'){renderProjects();syncUserMenu();return}renderSide();const el=$('#page-content');el.innerHTML=selectedMeeting?meetingDetail(selectedMeeting):({overview,meetings,work,journal,members,timeline,personal,today:todayAgenda,settings,profile:profilePage,projects:()=>renderProjects()}[currentView]||overview)();if(currentView==='members')$('.heading-actions')?.insertAdjacentHTML('afterbegin','<button class="button" data-action="accept-invite">接受邀请码</button>');if(selectedMeeting){document.querySelector('.meeting-detail-grid>div:first-child')?.insertAdjacentHTML('afterbegin',meetingTagSection(selectedMeeting));if(state.project.status!=='已归档'&&selectedMeeting.status==='待召开'&&(currentUser.role==='组长'||meetingMembers(selectedMeeting).some(p=>p.id===currentUser.id)||belongsToCurrent(selectedMeeting.hostId,selectedMeeting.host)||belongsToCurrent(selectedMeeting.organizerId,selectedMeeting.organizer)))$('.heading-actions')?.insertAdjacentHTML('beforeend','<button class="button" data-action="manage-reminders">设置会议提醒</button>');if(state.project.status!=='已归档'&&selectedMeeting.status==='待召开'&&(currentUser.role==='组长'||belongsToCurrent(selectedMeeting.organizerId,selectedMeeting.organizer)))$('.heading-actions')?.insertAdjacentHTML('beforeend','<button class="button" data-action="edit-meeting">编辑安排</button>');const history=[...state.events.filter(ev=>ev.meetingId===selectedMeeting.id).map(ev=>({title:ev.title,detail:ev.detail,at:ev.at||ev.date})),...(selectedMeeting.changes||[]).map(change=>({title:'修改会议安排',detail:`${change.by} · ${change.before.date} ${change.before.start} → ${change.after.date} ${change.after.start}`,at:change.at}))].sort((a,b)=>String(b.at).localeCompare(String(a.at)));if(history.length){const panel=document.createElement('section');panel.className='detail-section';panel.innerHTML=`<h3>会议操作历史</h3>${history.map(ev=>`<div class="history-event"><b>${esc(ev.title)}</b><small>${esc(ev.detail)} · ${esc(String(ev.at).slice(0,16).replace('T',' '))}</small></div>`).join('')}`;document.querySelector('.meeting-detail-grid>div:last-child')?.append(panel)}if(state.project.status!=='已归档'&&selectedMeeting.status==='进行中'&&meetingMembers(selectedMeeting).some(p=>p.id===currentUser.id)&&!hasChecked(selectedMeeting,currentUser)){const own=document.querySelector(`[data-attendee="${CSS.escape(currentUser.id)}"]`);own?.insertAdjacentHTML('beforeend','<button class="button small" data-action="checkin">本人签到</button>')}}}
function toast(text){const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;$('#toast-region').append(el);setTimeout(()=>el.remove(),2800)}
async function copyInviteCode(code){const value=String(code||'').trim();if(!value)return toast('没有可复制的邀请码');const fallback=async()=>{const field=document.createElement('textarea');field.value=value;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();const copied=document.execCommand('copy');field.remove();if(copied)toast('邀请码已复制');else await appPrompt('复制邀请码','请手动复制下方内容',value)};if(navigator.clipboard?.writeText)navigator.clipboard.writeText(value).then(()=>toast('邀请码已复制')).catch(fallback);else await fallback()}
