function settleAppDialog(value){const resolve=appDialogResolve;appDialogResolve=null;$('#modal-layer').hidden=true;$('#modal-layer').innerHTML='';resolve?.(value)}
function appConfirm(message,{title='请确认',confirmText='继续',danger=false,detail=''}={}){return new Promise(resolve=>{appDialogResolve=resolve;const layer=$('#modal-layer');layer.innerHTML=`<div class="modal compact-confirm" role="dialog" aria-modal="true"><div class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" data-action="app-dialog-cancel" aria-label="关闭">×</button></div><div class="modal-body"><p class="confirm-copy">${esc(message)}</p>${detail?`<small class="confirm-detail">${esc(detail)}</small>`:''}</div><div class="form-foot"><button class="button" data-action="app-dialog-cancel">取消</button><button class="button ${danger?'danger-button':'primary'}" data-action="app-dialog-accept">${esc(confirmText)}</button></div></div>`;layer.hidden=false;layer.querySelector('[data-action="app-dialog-accept"]')?.focus()})}
function appPrompt(title,message,defaultValue=''){return new Promise(resolve=>{appDialogResolve=resolve;const layer=$('#modal-layer');layer.innerHTML=`<div class="modal compact-confirm" role="dialog" aria-modal="true"><div class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" data-action="app-dialog-cancel" aria-label="关闭">×</button></div><div class="modal-body"><p class="confirm-copy">${esc(message)}</p><input class="dialog-prompt-input" maxlength="40" value="${esc(defaultValue)}"></div><div class="form-foot"><button class="button" data-action="app-dialog-cancel">取消</button><button class="button primary" data-action="app-dialog-prompt">保存</button></div></div>`;layer.hidden=false;const input=layer.querySelector('.dialog-prompt-input');input?.focus();input?.select()})}
