function syncLogAssociation(source='init'){const form=document.querySelector('#log-form');if(!form)return;const meeting=form.elements.namedItem('meetingId'),assignment=form.elements.namedItem('linkAssignmentId');if(!meeting||!assignment)return;const selected=assignment.selectedOptions?.[0];if(source==='assignment'&&assignment.value)meeting.value=selected?.dataset.meetingId||'';if(source==='meeting'&&!meeting.value)assignment.value='';for(const option of assignment.options){if(!option.value){option.disabled=false;continue}option.disabled=!!meeting.value&&option.dataset.meetingId!==meeting.value}if(assignment.value&&meeting.value&&assignment.selectedOptions[0]?.dataset.meetingId!==meeting.value)assignment.value='';const hint=form.querySelector('[data-log-link-hint]');if(hint)hint.textContent=assignment.value?'已自动匹配分工所属会议；修改会议会取消不匹配的分工关联。':'选择分工后会自动匹配所属会议。'}
document.addEventListener('change',e=>{if(!e.target.closest('#log-form'))return;modalDirty=true;if(e.target.name==='linkAssignmentId')syncLogAssociation('assignment');else if(e.target.name==='meetingId')syncLogAssociation('meeting')});
