document.addEventListener('change',e=>{if(e.target.id==='project-filter'){projectStatus=e.target.value;renderProjects()}if(e.target.id==='meeting-filter'){meetingFilter=e.target.value;render()}if(e.target.id==='meeting-from'){meetingFrom=e.target.value;render()}if(e.target.id==='meeting-to'){meetingTo=e.target.value;render()}if(e.target.id==='meeting-mine-filter'){meetingMine=e.target.checked;render()}if(e.target.id==='event-filter')document.querySelectorAll('[data-event-kind]').forEach(x=>x.hidden=e.target.value!=='全部动态'&&x.dataset.eventKind!==e.target.value);if(e.target.id==='log-author-filter'){logAuthorFilter=e.target.value;render()}if(e.target.id==='log-from'){logFrom=e.target.value;render()}if(e.target.id==='log-to'){logTo=e.target.value;render()}if(e.target.id==='personal-person-filter'){currentPerson=e.target.value;render()}if(e.target.id==='event-filter'){eventTypeFilter=e.target.value;eventLimit=20;render()}if(e.target.id==='event-person-filter'){eventPersonFilter=e.target.value;eventLimit=20;render()}if(e.target.id==='event-from'){eventFrom=e.target.value;eventLimit=20;render()}if(e.target.id==='event-to'){eventTo=e.target.value;eventLimit=20;render()}});
