document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='edit-log'){const log=state.logs.find(x=>x.id===b.dataset.id);if(log)openNewLog(log)}if(b.dataset.action==='upload-file'){const input=document.createElement('input');input.type='file';input.accept='.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.md,.png,.jpg,.jpeg,.webp,.gif';input.multiple=true;input.onchange=async()=>{if(!input.files.length)return;if(input.files.length>5){toast('单次最多选择5个文件');return}const failures=[],successes=[];for(const file of input.files){try{const fd=new FormData();fd.append('meetingId',selectedMeeting.id);fd.append('file',file);const r=await uploadWithOperation('/api/files',fd),x=await r.json();if(!r.ok)throw Error(x.error||'上传失败');successes.push(file.name)}catch(err){failures.push(`${file.name}：${err.message}`)}}try{state=await request('/api/state');selectedMeeting=state.meetings.find(m=>m.id===selectedMeeting.id);render()}catch(err){toast(`文件上传结果已返回，但列表刷新失败：${err.message}`);return}if(failures.length)modal('资料上传结果',`<p>成功 ${successes.length} 个，失败 ${failures.length} 个。失败文件不会生成可下载记录。</p><ul>${failures.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="subtle">可再次点击“上传资料”，只选择失败文件重试。</p>`,'知道了');else toast(`资料上传成功（${successes.length} 个）`)};input.click()}if(b.dataset.action==='checkin'){try{const m=await request('/api/meetings/checkin','POST',{meetingId:selectedMeeting.id});Object.assign(selectedMeeting,m);state.meetings[state.meetings.findIndex(x=>x.id===m.id)]=m;toast('签到成功');render()}catch(err){toastError(err.message)}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='edit-meeting'&&selectedMeeting)openEditMeeting(selectedMeeting);if(b.dataset.action==='supplement'&&selectedMeeting){const person=state.people.find(p=>p.id===b.dataset.person);modal('补录签到',`<form id="supplement-form"><input type="hidden" name="personId" value="${esc(person?.id)}"><div class="field"><label>参会成员</label><input readonly value="${esc(person?personLabel(person):'未知成员')}"></div><div class="field"><label>补签原因 *</label><textarea name="reason" required maxlength="500" placeholder="说明补签原因"></textarea></div></form>`,'确认补签')}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action=logout]');if(!b||b.disabled)return;b.disabled=true;try{const response=await fetch('/api/logout',{method:'POST',credentials:'same-origin',signal:AbortSignal.timeout(8000)});if(!response.ok)throw new Error('服务器暂未确认退出请求');currentUser=null;state=null;setConnection('offline','已退出登录');renderAuth('login')}catch{currentUser=null;state=null;setConnection('offline','请重新登录');renderAuth('login');toastError('已返回登录页面，服务器暂时无法确认退出状态；请检查连接后重新登录。')}finally{b.disabled=false}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-auth-mode]');if(b)renderAuth(b.dataset.authMode)});
