document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;if(button.dataset.action==='download-backup'){button.disabled=true;button.textContent='正在生成备份…';try{const r=await fetch('/api/backup',{credentials:'same-origin',headers:{'X-Project-Id':currentProjectId}});if(!r.ok){const err=await r.json();throw Error(err.error||'备份失败')}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${state.project.name}-项目备份.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('项目备份已下载')}catch(err){toastError(err.message)}finally{button.disabled=false;button.textContent='下载项目备份压缩包'}}if(button.dataset.action==='choose-restore')$('#backup-file')?.click()});
document.addEventListener('change',async e=>{if(e.target.id!=='backup-file'||!e.target.files?.length)return;const file=e.target.files[0];if(file.size>110*1024*1024){toast('备份文件不能超过110兆字节');e.target.value='';return}if(!await appConfirm(`使用“${file.name}”覆盖项目“${state.project.name}”的数据？`,{title:'恢复备份',confirmText:'覆盖恢复',danger:true,detail:'建议先备份当前项目。'})){e.target.value='';return}try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=0x8000)binary+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));const archive=btoa(binary);toast('正在验证备份并恢复项目…');const restored=await request('/api/backup/restore','POST',{archive});await load();toast(`项目已恢复，包含 ${restored.files} 个附件`)}catch(err){toastError(err.message)}finally{e.target.value=''}});
document.addEventListener('mousedown',e=>{const tool=e.target.closest('[data-editor-command]');if(tool){const sel=getSelection();if(sel?.rangeCount)tool.closest('.rich-editor-wrap').dataset.savedRange='1';e.preventDefault()}});document.addEventListener('click',async e=>{const listItem=e.target.closest('[data-rich-editor] li[data-checked]');if(listItem&&e.offsetX<28){const checked=listItem.dataset.checked!=='true';listItem.dataset.checked=String(checked);listItem.textContent=`${checked?'☑':'☐'} ${listItem.textContent.replace(/^[☐☑]\s*/, '')}`;listItem.closest('[data-rich-editor]').dispatchEvent(new InputEvent('input',{bubbles:true}));return}const tool=e.target.closest('[data-editor-command]');if(!tool)return;const editor=tool.closest('.rich-editor-wrap')?.querySelector('[data-rich-editor]');if(!editor)return;const cmd=tool.dataset.editorCommand;editor.focus();if(cmd==='image'){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(file.size>10*1024*1024){toast('正文图片不能超过10兆字节');return}try{const fd=new FormData();fd.append('file',file);fd.append('kind',editor.dataset.richEditor);fd.append('recordId',editor.closest('.rich-editor-wrap').dataset.recordId||'');const r=await fetch('/api/editor-images',{method:'POST',credentials:'same-origin',headers:{'X-Project-Id':currentProjectId},body:fd});const result=await r.json();if(!r.ok)throw Error(result.error||'图片上传失败');document.execCommand('insertHTML',false,`<img src="${esc(result.url)}" alt="${esc(file.name)}">`);editor.dispatchEvent(new InputEvent('input',{bubbles:true}));}catch(err){toastError(err.message)}};input.click();return}if(cmd==='link'){const href=await appPrompt('插入链接','输入 http:// 或 https:// 开头的链接','https://');if(href&&/^https?:\/\//i.test(href))document.execCommand('createLink',false,href);else if(href)toast('链接必须以 http:// 或 https:// 开头')}else if(/^h[1-3]$/.test(cmd))document.execCommand('formatBlock',false,cmd);else if(cmd==='blockquote')document.execCommand('formatBlock',false,'blockquote');else if(cmd==='color'||cmd==='highlight'){if(!getSelection()?.toString()){toast('请先选中需要设置样式的文字');return}const color=await appPrompt(cmd==='color'?'文字颜色':'高亮颜色','输入十六进制颜色',cmd==='color'?'#3158d9':'#fff0b3');if(color&&/^#[0-9a-f]{3,8}$/i.test(color))document.execCommand('insertHTML',false,`<span style="${cmd==='color'?'color':'background-color'}:${color}">${getSelection()?.toString()||'选中文字'}</span>`);else if(color)toast('请输入有效的十六进制颜色')}else if(cmd==='checklist')document.execCommand('insertHTML',false,'<ul data-checklist="true"><li data-checked="false">☐ 清单事项</li></ul>');else if(cmd==='hr')document.execCommand('insertHTML',false,'<hr><p><br></p>');else if(cmd==='table')document.execCommand('insertHTML',false,'<table><tbody><tr><th>标题一</th><th>标题二</th></tr><tr><td>内容</td><td>内容</td></tr></tbody></table><p><br></p>');else if(['add-row','add-column','delete-row','delete-column'].includes(cmd)){const sel=getSelection(),cell=sel?.anchorNode?.parentElement?.closest('td,th'),table=cell?.closest('table');if(!cell||!table){toast('请先将光标放在需要调整的表格内');return}const row=cell.parentElement,index=cell.cellIndex;if(cmd==='add-row'){if(table.rows.length>=20){toast('每张表格最多20行');return}const tr=table.insertRow(row.rowIndex+1);for(let i=0;i<row.cells.length;i++){const c=tr.insertCell();c.innerHTML='内容'}}else if(cmd==='add-column'){if(row.cells.length>=10){toast('每张表格最多10列');return}for(const r of table.rows){const c=r.insertCell(index+1);c.innerHTML='内容'}}else if(cmd==='delete-row'){if(table.rows.length<=1){toast('表格至少保留一行');return}table.deleteRow(row.rowIndex)}else{if(row.cells.length<=1){toast('表格至少保留一列');return}for(const r of table.rows)r.deleteCell(index)}}else if(cmd==='checklist-toggle'){const li=getSelection()?.anchorNode?.parentElement?.closest('li');if(li){const checked=li.dataset.checked!=='true';li.dataset.checked=String(checked);li.textContent=`${checked?'☑':'☐'} ${li.textContent.replace(/^[☐☑]\s*/, '')}`}}else document.execCommand(cmd,false,null);editor.dispatchEvent(new InputEvent('input',{bubbles:true}));});
document.addEventListener('paste',async e=>{const editor=e.target.closest('[data-rich-editor]');if(!editor)return;const image=[...(e.clipboardData?.items||[])].find(x=>x.type.startsWith('image/'));if(!image){const source=e.clipboardData?.getData('text/html');if(source){e.preventDefault();const doc=new DOMParser().parseFromString(source,'text/html'),allowed=new Set(['P','BR','H1','H2','H3','STRONG','B','EM','I','U','S','UL','OL','LI','BLOCKQUOTE','A','TABLE','THEAD','TBODY','TR','TD','TH','HR','SPAN']);doc.querySelectorAll('script,style,iframe,object,embed,svg,math,form,img').forEach(n=>n.remove());const clean=node=>{for(const child of [...node.children]){if(!allowed.has(child.tagName)){child.replaceWith(...child.childNodes);continue}const href=child.getAttribute('href')||'',style=child.getAttribute('style')||'',checked=child.getAttribute('data-checked'),checklist=child.getAttribute('data-checklist');for(const a of [...child.attributes])child.removeAttribute(a.name);if(child.tagName==='A'&&/^https?:\/\//i.test(href))child.setAttribute('href',href);if(child.tagName==='SPAN'){const color=style.match(/(?:^|;)\s*color\s*:\s*(#[0-9a-f]{3,8})/i)?.[1],bg=style.match(/(?:^|;)\s*background-color\s*:\s*(#[0-9a-f]{3,8})/i)?.[1];const safe=[color&&`color:${color}`,bg&&`background-color:${bg}`].filter(Boolean).join(';');if(safe)child.setAttribute('style',safe)}if(child.tagName==='LI'&&['true','false'].includes(checked))child.setAttribute('data-checked',checked);if(child.tagName==='UL'&&checklist==='true')child.setAttribute('data-checklist','true');clean(child)}};clean(doc.body);document.execCommand('insertHTML',false,doc.body.innerHTML);editor.dispatchEvent(new InputEvent('input',{bubbles:true}));return}return;}e.preventDefault();const file=image.getAsFile();if(!file)return;try{const fd=new FormData();const ext=({'image/png':'png','image/jpeg':'jpg'})[file.type];if(!ext){toast('粘贴图片仅支持常见图片格式');return}if(file.size>10*1024*1024){toast('正文图片不能超过10兆字节');return}fd.append('file',file,`pasted-image.${ext}`);fd.append('kind',editor.dataset.richEditor);fd.append('recordId',editor.closest('.rich-editor-wrap').dataset.recordId||'');const r=await fetch('/api/editor-images',{method:'POST',credentials:'same-origin',headers:{'X-Project-Id':currentProjectId},body:fd});const result=await r.json();if(!r.ok)throw Error(result.error||'图片粘贴失败');editor.focus();document.execCommand('insertHTML',false,`<img src="${esc(result.url)}" alt="粘贴图片">`);editor.dispatchEvent(new InputEvent('input',{bubbles:true}));}catch(err){toastError(err.message)}});
$('#sidebar').addEventListener('click',e=>{const nav=e.target.closest('.nav-item[data-view]');if(!nav)return;e.preventDefault();e.stopPropagation();currentView=nav.dataset.view;if(currentView==='personal')currentPerson=currentUser?.id||'';selectedMeeting=null;render();if(currentView==='today')void refreshToday({silent:true});$('#sidebar').classList.remove('open')},true);
