let projectEventsView={projectId:null,userId:null,projectName:'',filters:{kind:'',memberId:'',from:'',to:''},data:null,loading:false,error:''};
function ensureProjectEvents(){
  if(projectEventsView.projectId===currentProjectId&&projectEventsView.userId===currentUser.id)return;
  projectEventsAbort?.abort();++projectEventsVersion;
  projectEventsView={projectId:currentProjectId,userId:currentUser.id,projectName:state.project.name,filters:{kind:'',memberId:'',from:'',to:''},data:{items:[],kinds:[],members:state.people,total:0},loading:true,error:''};
  queueMicrotask(()=>void refreshProjectEvents());
}
async function refreshProjectEvents(more=false){
  if(currentView!=='timeline'||projectTimelineView!=='events'||!currentUser)return;
  const projectId=currentProjectId,userId=currentUser.id,filters={...projectEventsView.filters},version=++projectEventsVersion;
  projectEventsAbort?.abort();const controller=projectEventsAbort=new AbortController();
  if(filters.from&&filters.to&&filters.from>filters.to){projectEventsView.loading=false;projectEventsView.error='开始日期不能晚于结束日期。';render();return}
  projectEventsView.loading=true;projectEventsView.error='';render();
  const query=new URLSearchParams({...filters,limit:'20'});if(more&&projectEventsView.data?.nextCursor)query.set('cursor',projectEventsView.data.nextCursor);
  const active=()=>version===projectEventsVersion&&currentProjectId===projectId&&currentUser?.id===userId;
  const timer=setTimeout(()=>controller.abort(),15000);
  try{
    const response=await fetch('/api/project-events?'+query,{credentials:'same-origin',headers:{'X-Project-Id':projectId},signal:controller.signal}),data=await response.json();
    if(!response.ok)throw Error(data.error||'事件记录加载失败');if(!Array.isArray(data.items))throw Error('事件数据无效');if(!active())return;
    if(more){const previous=projectEventsView.data.items,ids=new Set(previous.map(e=>e.id));data.items=[...previous,...data.items.filter(e=>!ids.has(e.id))]}
    projectEventsView.data=data;projectEventsView.projectName=state.project.name;
  }catch(error){if(active())projectEventsView.error=error.name==='AbortError'?'加载超时，请重试。':error.message}
  finally{clearTimeout(timer);if(active()){projectEventsView.loading=false;if(currentView==='timeline'&&projectTimelineView==='events')render()}}
}
document.addEventListener('change',event=>{
  const fields={'project-event-kind':'kind','project-event-member':'memberId','project-event-from':'from','project-event-to':'to'},field=fields[event.target.id];if(!field)return;
  projectEventsView.filters[field]=event.target.value;projectEventsView.data={...projectEventsView.data,items:[],total:0,hasMore:false,nextCursor:null};void refreshProjectEvents();
});
document.addEventListener('click',async event=>{
  const control=event.target.closest('[data-action]');if(!control)return;const action=control.dataset.action;
  if(action==='project-record-tab'){projectTimelineView=control.dataset.tab==='events'?'events':'meetings';render();if(projectTimelineView==='events'&&!projectEventsView.loading)void refreshProjectEvents();return}
  if(action==='project-events-clear'){projectEventsView.filters={kind:'',memberId:'',from:'',to:''};await refreshProjectEvents();return}
  if(['project-events-refresh','project-events-retry'].includes(action)){await refreshProjectEvents(!!projectEventsView.data?.nextCursor&&action==='project-events-retry');return}
  if(action==='project-events-more'){if(!projectEventsView.loading)await refreshProjectEvents(true);return}
  if(action!=='project-event-source')return;
  const projectId=currentProjectId,userId=currentUser.id,recordView=projectTimelineView,sourceVersion=++projectEventSourceVersion;control.disabled=true;
  try{
    const source=await request('/api/project-events/source?id='+encodeURIComponent(control.dataset.id),'GET',undefined,projectId);
    const fresh=await request('/api/state','GET',undefined,projectId);
    if(sourceVersion!==projectEventSourceVersion||currentProjectId!==projectId||currentUser?.id!==userId||currentView!=='timeline'||projectTimelineView!==recordView)return;
    state=fresh;await openProjectEventSource(source,projectId);
  }catch(error){if(sourceVersion===projectEventSourceVersion&&currentProjectId===projectId&&currentUser?.id===userId&&currentView==='timeline'&&projectTimelineView===recordView){toast(error.message);if(recordView==='events')void refreshProjectEvents()}}
  finally{if(control.isConnected)control.disabled=false}
});
async function openProjectEventSource(source,projectId){
  const {type,id,parentId}=source;selectedMeeting=null;
  if(type==='file'){const file=state.files.find(f=>f.id===id);if(!file)throw Error('资料已不存在');const link=document.createElement('a');link.href='/api/files/download?id='+encodeURIComponent(id)+'&projectId='+encodeURIComponent(projectId);link.download=file.name;document.body.append(link);link.click();link.remove();return}
  if(type==='project'){currentView='settings';render();return}
  if(type==='member'||type==='invite'){currentView='members';render();return}
  if(type==='meeting'||type==='minutes'){selectedMeeting=state.meetings.find(m=>m.id===id);if(!selectedMeeting)throw Error('原会议已不存在');currentView='meetings';render();return}
  if(type==='assignment'||type==='log'){
    if(type==='assignment'){currentView='work';showMine=false;workMemberFilter='全部成员';workQuery=''}else{currentView='journal';logAuthorFilter='全部成员';logQuery='';logFrom='';logTo=''}
    render();const target=document.querySelector(type==='assignment'?`[data-assignment="${CSS.escape(id)}"]`:`[data-log="${CSS.escape(id)}"]`);if(!target)throw Error('来源记录已不存在');target.scrollIntoView({block:'center',behavior:'smooth'});target.classList.add('focus-highlight');setTimeout(()=>target.classList.remove('focus-highlight'),1800);return;
  }
  let record,label,content;
  const file=state.files.find(f=>f.id===(parentId||id));
  if(type==='audio'){record=file;label=file?.name;content=`<audio class="project-source-audio" controls src="/api/audio/stream?id=${encodeURIComponent(id)}&projectId=${encodeURIComponent(projectId)}"></audio>`}
  else if(type==='transcript'){record=file?.transcriptions?.find(t=>t.id===id);label=`${file?.name||'录音'} · 转写第 ${record?.version||1} 版`;content=record?.editedText||record?.rawText||'尚无转写文字'}
  else if(type==='file-analysis'){record=file?.analyses?.find(a=>a.id===id);label=`${file?.name||'资料'} · 分析第 ${record?.version||1} 版`;content=record?.result}
  else if(type==='audio-analysis'){record=file?.transcriptions?.find(t=>t.id===source.transcriptId)?.analyses?.find(a=>a.id===id);label=`${file?.name||'录音'} · 分析第 ${record?.version||1} 版`;content=record?.result}
  else if(type==='meeting-analysis'){const meeting=state.meetings.find(m=>m.id===parentId);record=meeting?.materialAnalyses?.find(a=>a.id===id);label=`${meeting?.title||'会议'} · 综合分析第 ${record?.version||1} 版`;content=record?.result}
  if(!record)throw Error('来源记录已不存在');modal(projectEventSourceNames[type]||'来源记录',`<h3>${esc(label||'来源记录')}</h3>${type==='audio'?content:`<div class="project-source-text">${esc(content||'暂无内容')}</div>`}`,'关闭');
}


function toastError(text='操作未完成，请稍后重试。'){const el=document.createElement('div');el.className='toast error';el.setAttribute('role','alert');el.textContent=text;$('#toast-region').append(el);setTimeout(()=>el.remove(),4200)}


async function downloadLinkInApp(link,successText,fallback){const original=link.textContent;link.setAttribute('aria-disabled','true');link.textContent='准备下载…';try{const response=await fetch(link.href,{credentials:'same-origin',headers:{'X-Project-Id':currentProjectId}});if(!response.ok){let message='';try{const result=await response.json();message=result.error||''}catch{}if(response.status===401){currentUser=null;state=null;renderAuth()}throw new Error(message||(response.status===401?'登录状态已过期，请重新登录。':fallback))}const blob=await response.blob(),disposition=response.headers.get('content-disposition')||'',encoded=disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1],url=new URL(link.href),format=url.searchParams.get('format'),filename=encoded?decodeURIComponent(encoded):format?`项目记录.${format}`:link.download||'项目附件',objectUrl=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=objectUrl;anchor.download=filename;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),1000);toast(successText)}catch(error){toastError(error instanceof TypeError?'暂时无法连接服务器，请稍后重试。':error.message||fallback)}finally{link.removeAttribute('aria-disabled');link.textContent=original}}


