function archiveCard() {
  const project = state.project;
  const leader = currentUser.role === '组长';
  const archived = project.status === '已归档';
  const open = state.meetings.filter(m => ['进行中','待召开'].includes(m.status))
    .sort((a,b) => Number(b.status === '进行中') - Number(a.status === '进行中'));
  const rows = open.map(m => {
    const action = m.status === '进行中' ? '结束会议' : '取消会议';
    return `<li><button class="text-link" data-open-meeting="${esc(m.id)}">${esc(m.title)} ↗</button> · ${esc(m.status)}
      ${leader ? `<button class="button small" data-action="archive-resolve" data-id="${esc(m.id)}">${action}</button>` : ''}</li>`;
  }).join('');
  let content;
  if (archived) {
    content = '<p>已归档 · '+esc(project.archivedBy || '归档人未记录')+' · '+esc(project.archivedAt ? new Date(project.archivedAt).toLocaleString('zh-CN') : '时间未记录')+'</p>';
  } else if (rows) {
    content = `<p>项目进行中 · 以下 ${open.length} 场会议尚未结束或取消，暂时无法归档。</p><ul class="archive-list">${rows}</ul>` + (leader ? button('归档项目','archive-project',false,'danger') : '');
  } else {
    content = '<p>所有会议已处理，可以归档。</p>' + (leader ? button('归档项目','archive-project',false,'danger') : '');
  }
  return '<section class="settings-card"><h3>项目归档</h3>'+content+'</section>';
}
document.addEventListener('click',async event => {
  const target = event.target.closest('[data-action="archive-resolve"]');
  if (!target) return;
  const m = state.meetings.find(item => item.id === target.dataset.id);
  if (!m) return;
  const cancelling = m.status === '待召开';
  let reason = '';
  if (cancelling) {
    reason = await appPrompt('取消「'+m.title+'」','请填写取消原因');
    if (!reason?.trim()) return;
  } else if (!await appConfirm('确认结束「'+m.title+'」？',{title:'结束会议',confirmText:'确认结束'})) return;
  try {
    await request('/api/meetings/status','PATCH',{id:m.id,status:cancelling?'已取消':'已结束',reason});
    state = await request('/api/state');
    render();
  } catch (err) { toastError(err.message); }
});

